CREATE TABLE IF NOT EXISTS meetings (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, scheduledAt DATETIME NOT NULL, endTime DATETIME, timezone VARCHAR(50) DEFAULT 'UTC', location VARCHAR(255), meetingType ENUM('board', 'committee', 'annual', 'special') DEFAULT 'board', status ENUM('scheduled', 'inProgress', 'completed', 'cancelled') DEFAULT 'scheduled', recordingUrl VARCHAR(500), transcriptionUrl VARCHAR(500), createdBy INT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_org_meeting (organizationId), INDEX idx_meeting_status (status));
CREATE TABLE IF NOT EXISTS meetingParticipants (id INT PRIMARY KEY AUTO_INCREMENT, meetingId INT NOT NULL, userId INT NOT NULL, status ENUM('invited', 'accepted', 'declined', 'attended', 'absent') DEFAULT 'invited', joinedAt DATETIME, leftAt DATETIME, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agendas (id INT PRIMARY KEY AUTO_INCREMENT, meetingId INT NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, orderIndex INT DEFAULT 0, duration INT, status ENUM('pending', 'inProgress', 'completed') DEFAULT 'pending', createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_meeting_agenda (meetingId));

